#include <Arduino.h>
const int buttonPin = 2;    
const int ledPin = 3;        
int buttonState;            
int lastButtonState = HIGH; 
int ledState = HIGH;         
unsigned long lastDebounceTime = 0;  
unsigned long debounceDelay = 50;    

void setup();
void loop();
void setup() {
  pinMode(buttonPin, INPUT_PULLUP);  
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, ledState);
}
void loop() {
  int reading = digitalRead(buttonPin);
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }
  if ((millis() - lastDebounceTime) > debounceDelay) {
    if (reading != buttonState) {
      buttonState = reading;
      if (buttonState == LOW) {
        ledState = !ledState;  
        digitalWrite(ledPin, ledState);
      }
    }
  }
  lastButtonState = reading;
}

#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int BUTTON_PIN = 2;
const byte segmentCodes[] = {
  0b11000000,
  0b11111001,
  0b10100100,
  0b10110000,
  0b10011001,
  0b10010010,
  0b10000010,
  0b11111000,
  0b10000000,
  0b10010000,
};
int currentNumber = 0;

void setup();
void loop();
void displayNumber(int number);
void setup() {
  Serial.begin(9600);
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP); 
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, segmentCodes[0]); 
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, segmentCodes[0]);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    delay(20); 
    if (digitalRead(BUTTON_PIN) == LOW) {
      currentNumber += 37;
      if (currentNumber > 99) {
        currentNumber = 0;
      }
      displayNumber(currentNumber);
      while (digitalRead(BUTTON_PIN) == LOW); 
    }
  }
}
void displayNumber(int number) {
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
